import java.util.NoSuchElementException;

public class TicketServiceSystem {
    interface TicketQueue {
        void enqueue(String ticket);
        String dequeue();
        String peek();
        int size();
    }

    static void requireTicket(String ticket) {
        if (ticket == null || ticket.isBlank()) {
            throw new IllegalArgumentException("ticket cannot be blank");
        }
    }

    static class CircularTicketQueue implements TicketQueue {
        private final String[] items;
        private int head;
        private int size;

        CircularTicketQueue(int capacity) {
            if (capacity <= 0) throw new IllegalArgumentException("capacity must be positive");
            items = new String[capacity];
        }

        public void enqueue(String ticket) {
            requireTicket(ticket);
            if (size == items.length) throw new IllegalStateException("queue is full");
            int tail = (head + size) % items.length;
            items[tail] = ticket;
            size++;
        }

        public String dequeue() {
            String ticket = peek();
            items[head] = null;
            head = (head + 1) % items.length;
            size--;
            return ticket;
        }

        public String peek() {
            if (size == 0) throw new NoSuchElementException("queue is empty");
            return items[head];
        }

        public int size() {
            return size;
        }
    }

    static class LinkedTicketQueue implements TicketQueue {
        private static class Node {
            final String ticket;
            Node next;
            Node(String ticket) { this.ticket = ticket; }
        }

        private Node head;
        private Node tail;
        private int size;

        public void enqueue(String ticket) {
            requireTicket(ticket);
            Node added = new Node(ticket);
            if (tail == null) head = added;
            else tail.next = added;
            tail = added;
            size++;
        }

        public String dequeue() {
            String ticket = peek();
            head = head.next;
            size--;
            if (head == null) tail = null;
            return ticket;
        }

        public String peek() {
            if (head == null) throw new NoSuchElementException("queue is empty");
            return head.ticket;
        }

        public int size() {
            return size;
        }
    }

    static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw error;
        }
        throw new AssertionError("expected " + type.getSimpleName());
    }

    static void checkCommon(TicketQueue queue) {
        expect(NoSuchElementException.class, queue::dequeue);
        expect(NoSuchElementException.class, queue::peek);
        expect(IllegalArgumentException.class, () -> queue.enqueue(" "));
        queue.enqueue("A");
        assert queue.peek().equals("A");
        assert queue.dequeue().equals("A");
        assert queue.size() == 0;
        queue.enqueue("B");
        queue.enqueue("C");
        assert queue.dequeue().equals("B");
        queue.enqueue("D");
        assert queue.dequeue().equals("C");
        assert queue.dequeue().equals("D");
        assert queue.size() == 0;
    }

    public static void main(String[] args) {
        checkCommon(new CircularTicketQueue(2));
        checkCommon(new LinkedTicketQueue());

        CircularTicketQueue bounded = new CircularTicketQueue(2);
        bounded.enqueue("A");
        bounded.enqueue("B");
        expect(IllegalStateException.class, () -> bounded.enqueue("C"));
        assert bounded.dequeue().equals("A");
        bounded.enqueue("C");
        assert bounded.dequeue().equals("B");
        assert bounded.dequeue().equals("C");

        expect(IllegalArgumentException.class, () -> new CircularTicketQueue(0));
        System.out.println("weekend-queue checks: OK");
    }
}
